    try:y=float(x)
    except (ValueError,TypeError,OverflowError):raise ValueError('Número real finito necessário') from None
    if not isfinite(y):raise ValueError('Número real finito necessário')
    return y

def paired(x,y):
    a=[finite(v) for v in x];b=[finite(v) for v in y]
    if not a or len(a)!=len(b):raise ValueError('Dados não vazios de mesmo tamanho necessários')
    return a,b

def logistic_loss(x,y,w,b):
    x,y=paired(x,y)
    if any(v not in [0,1] for v in y):raise ValueError('Rótulos binários necessários')
    z=[finite(w*a+b) for a in x]
    return sum(max(v if t==0 else -v,0)+log1p(exp(-abs(v))) for v,t in zip(z,y))/len(y)

def sigmoid(z):
    z=finite(z)
    if z>=0:v=exp(-z);return 1/(1+v)
    v=exp(z);return v/(1+v)

def logistic_gradient(x,y,w,b):
    x,y=paired(x,y)
    if any(v not in [0,1] for v in y):raise ValueError('Rótulos binários necessários')
    errors=[sigmoid(w*a+b) if t==0 else -sigmoid(-(w*a+b)) for a,t in zip(x,y)]
    return sum(e*a for e,a in zip(errors,x))/len(x),sum(errors)/len(x)

x=[-1,0,1];y=[0,0,1];w,b=.3,-.2;h=1e-6
g=logistic_gradient(x,y,w,b)[0]
fd=(logistic_loss(x,y,w+h,b)-logistic_loss(x,y,w-h,b))/(2*h)
assert abs(g-fd)<1e-8
